<?php if ($error): ?><div class="admin-error" role="alert"><?= escape($error) ?></div><?php endif; ?><?php if ($success): ?><div class="admin-success" role="status"><?= escape($success) ?></div><?php endif; ?>
<form method="post" class="admin-form settings-form"><input type="hidden" name="csrf" value="<?= escape(Csrf::token()) ?>">
<section class="admin-section"><p class="admin-eyebrow">CONTACT & POLICIES</p><h2>Business settings</h2><div class="form-two"><label>Phone<input name="phone" value="<?= escape($settings['phone'] ?? '') ?>"></label><label>Email<input type="email" name="email" value="<?= escape($settings['email'] ?? '') ?>"></label></div><label>Address / service area<input name="address" value="<?= escape($settings['address'] ?? '') ?>"></label><label>Timezone<input value="Africa/Accra" disabled></label><label>Customer change cutoff (hours)<input type="number" name="cutoff_hours" min="0" max="168" required value="<?= escape($settings['cutoff_hours'] ?? '24') ?>"></label><label>Cancellation policy<textarea name="cancellation_policy" rows="4" required><?= escape($settings['cancellation_policy'] ?? '') ?></textarea></label><label>Opening hours summary<textarea name="opening_text" rows="2"><?= escape($settings['opening_text'] ?? '') ?></textarea></label></section>
<section class="admin-section"><p class="admin-eyebrow">AVAILABILITY</p><h2>Business hours</h2><div class="business-hours-editor"><?php foreach (['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'] as $day=>$label): $row=$hours[$day]??['closed'=>1,'open_time'=>'','close_time'=>'']; ?><div><strong><?= $label ?></strong><label><input type="checkbox" name="business_hours[<?= $day ?>][closed]" value="1" <?= $row['closed']?'checked':'' ?>> Closed</label><input type="time" aria-label="<?= $label ?> opening time" name="business_hours[<?= $day ?>][open_time]" value="<?= escape($row['open_time'] ?? '') ?>"><input type="time" aria-label="<?= $label ?> closing time" name="business_hours[<?= $day ?>][close_time]" value="<?= escape($row['close_time'] ?? '') ?>"></div><?php endforeach; ?></div></section>
<section class="admin-section"><p class="admin-eyebrow">CLOSURE DATES</p><h2>Holidays</h2><p>One per line, formatted as <code>YYYY-MM-DD | Holiday name</code>.</p><textarea name="holiday_lines" rows="5" placeholder="2026-12-25 | Christmas Day"><?= escape(implode("\n", array_map(fn($h)=>$h['holiday_date'].' | '.$h['name'], $holidays))) ?></textarea></section>
<button class="admin-button" type="submit">Save business settings</button>
</form>
